out=[]
for n,dep,reg,pop in rows:
    pop=int(pop)
    if n in METRO:p='metro'
    elif n in TOURI:p='touri'
    elif n in AISE:p='aise'
    elif n in MIX:p='mixte'
    elif n in INDUS:p='indus'
    elif n in POPU or dep in PDEP:p='popu'
    elif dep in ('Hauts-de-Seine','Val-de-Marne','Yvelines','Essonne','Val-d\'Oise','Seine-et-Marne','Métropole de Lyon'):p='mixte'
    elif dep in ('Nord','Pas-de-Calais','Moselle'):p='indus'
    else:p='moy'
    out.append([n,dep,reg,pop,p])
REG=sorted(set(r[2] for r in out))
js='const REGIONS='+json.dumps(REG,ensure_ascii=False)+';\nconst COMM='+json.dumps([[a,b,REG.index(c),d,e] for a,b,c,d,e in out],ensure_ascii=False,separators=(',',':'))+';\n'
open('comm.js','w').write(js)
from collections import Counter
print(len(out),Counter(r[4] for r in out),len(js))
